shapes=[]
for r,c in G:
 for dr,dc in [(0,0),(0,1),(1,0),(1,1)]:
  sq={(r+dr,c+dc) for dr,dc in [(0,0),(0,1),(1,0),(1,1)]}
  if sq<=G: shapes.append((sq,1))
for r,c in G:
 for rr in range(r-1,r+1):
  for cc in range(c-1,c+1):
   box={(rr,cc),(rr,cc+1),(rr+1,cc),(rr+1,cc+1)}
   for miss in box:
    s=box-{miss}
    if s<=G: shapes.append((s,2+(miss[0]-rr)*2+(miss[1]-cc)))
shapes=list({(frozenset(s),k) for s,k in shapes})
def go(rem, chosen):
 if not rem:return chosen
 x=min(rem)
 for s,k in shapes:
  if x in s and s<=rem:
   z=go(rem-s,chosen+[(s,k)])
   if z:return z
